   "terms": [
    {
     "var": "foldable cell-phones produced",
     "coef": 500.0
    },
    {
     "var": "regular cell-phones produced",
     "coef": 300.0
    }
   ]
  },
  "constraints": [
   {
    "name": "hardware hours",
    "terms": [
     {
      "var": "foldable cell-phones produced",
      "coef": 10.0
     },
     {
      "var": "regular cell-phones produced",
      "coef": 3.0
     }
    ],
    "sense": "<=",
    "rhs": 200.0
   },
   {
    "name": "software hours",
    "terms": [
     {
      "var": "foldable cell-phones produced",
      "coef": 3.0
     },
     {
      "var": "regular cell-phones produced",
      "coef": 3.0
     }
